def bounded_ttl(requested_seconds, minimum_seconds, maximum_seconds):
    return min(max(requested_seconds, minimum_seconds), maximum_seconds)

def cache_key(tenant, resource):
    return f'{tenant}:{resource}'

files.tests/test_cache.py:
def test_ttl_clamps_both_bounds():
    assert bounded_ttl(1, 10, 90) == 10
    assert bounded_ttl(120, 10, 90) == 90

